{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'abn' src, service_name, metric, round(avg(value),4) av, round(min(value),4) mn, round(max(value),4) mx FROM abnormal_metrics WHERE service_name='geo' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, metric, round(avg(value),4), round(min(value),4), round(max(value),4) FROM normal_metrics WHERE service_name='geo' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2,3", "claim": "Geo container CPU usage rose from about 0.003 cores to a steady 1.0-1.6 cores across the abnormal window."},
        {"kind": "metric", "sql": "SELECT 'abn' src, service_name, metric, round(avg(value),4) av FROM abnormal_metrics WHERE service_name='geo' AND metric IN ('container.memory.working_set') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, metric, round(avg(value),4) FROM normal_metrics WHERE service_name='geo' AND metric IN ('container.memory.working_set') GROUP BY 1,2,3", "claim": "Geo working-set memory rose about 50%, from roughly 18MB to 27MB, alongside the CPU increase."},
        {"kind": "trace", "sql": "SELECT 'abn' src, service_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,3) p95 FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, attr_span_kind, count(*), round(quantile_cont(duration,0.95)/1e6,3) FROM normal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2,3", "claim": "Geo server span p95 stayed about 0.20ms, and search client spans to geo were unchanged, so latency impact is not visible."}
      ]
    }
  ],
  "propagation": [
    {"from": "geo", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT 'abn' src, service_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,3) p95 FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2,3", "claim": "search calls geo.Geo/Nearby on every request; the geo-side call path is the only link from the faulty service to search."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,3) p95 FROM abnormal_traces WHERE span_name='search.Search/Nearby' GROUP BY 1,2,3", "claim": "frontend's search.Search/Nearby client span wraps search's server span, carrying the call chain to the user-facing tier."}]}
  ]
}
